        colCurrentUserTeamsDirect,
        'Team Name' & " ; "
    )}",
    TraceSeverity.Information
);
ClearCollect(
    colAllCurrentUserTeamsRoles,
    Blank()
);
// This block added for Functionality to get editable countries
IfError(
    Trace(
        $"Try get user individuelle roles",
        TraceSeverity.Information
    );
    ClearCollect(
        colCurrentUserRoles,
        ForAll(
            colCurrentUserSystemsDirect As UR,
            {
                BussinessUnit: UR.'Business Unit'.Name,
                Name: UR.Name,
                Country: LookUp(
                    Countries_1,
                    'Business Unit'.'Business Unit' = UR.'Business Unit'.'Business Unit'
                ),
                UniqueID: UR.Role
            }
        )
    );
    ClearCollect(
        colCurrentUserTeamsRoles,
        Blank()
    );
    Trace(
        $"Try get user team security roles",
        TraceSeverity.Information
    );
    ClearCollect(
        colCurrentUserTeamsDirectTemp,
        colCurrentUserTeamsDirect
    );
    ForAll(
        colCurrentUserTeamsDirect,
        Collect(
            colAllCurrentUserTeamsRoles,
            LookUp(
                colCurrentUserTeamsDirect,
                'Team Name' = First(colCurrentUserTeamsDirectTemp).'Team Name'
            ).'Security Roles'
        );
        Remove(
            colCurrentUserTeamsDirectTemp,
            First(colCurrentUserTeamsDirectTemp)
        );
    );
    ClearCollect(
        colCurrentUserTeamsRoles,
        ForAll(
            colAllCurrentUserTeamsRoles As TR,
            {
                BussinessUnit: TR.'Business Unit'.Name,
                Name: TR.Name,
                Country: LookUp(
                    Countries_1,
                    'Business Unit'.'Business Unit' = TR.'Business Unit'.'Business Unit'
                ),
                UniqueID: TR.Role
            }
        )
    );
    ClearCollect(
        colAllCurrentUserRoles,
        Filter(
            colCurrentUserRoles,
            StartsWith(
                Name,
                "VSB"
            )
        ),
        Filter(
            colCurrentUserTeamsRoles,
            StartsWith(
                Name,
                "VSB"
            )
        )
    );
    ClearCollect(
        colDistinctCurrentUserTeamsRoles,
        ForAll(
            Distinct(
                colAllCurrentUserRoles,
                ThisRecord
            ),
            Value
        )
    );
    Trace(
        $"Success: User roles {JSON(
            DropColumns(
                colAllCurrentUserRoles,
                Country
            )
        )}",
        TraceSeverity.Information
    );
    ,
    Trace(
        $"Error: User cann't read 'Security Roles'. Internal error: originated on {FirstError.Source}. Message: {FirstError.Message & FirstError.Details.HttpResponse}",
        TraceSeverity.Critical
    )
);
IfError(
    ClearCollect(
        colUserCountries,
        ForAll(
            Filter(
                colDistinctCurrentUserTeamsRoles,
                And(
                    Not(IsBlank(Country)),
                    Name in [
                        "VSB - Project Manager Own Projects",
                        "VSB - Project Data Own Country"
                    ]
                )
            ),
            {
                id: Country.Country,
                name: Country.Name
            }
        )
    ),
    Trace(
        $"Error: User can't read available countries. Internal error: originated on {FirstError.Source}. Message: {FirstError.Message & FirstError.Details.HttpResponse}",
        TraceSeverity.Critical
    )
);
Set(
    gblCurrentUser,
    {
        Id: varCurrentUserProfile.Id,
        DisplayName: varCurrentUserProfile.DisplayName,
        Mail: varCurrentUserProfile.Mail,
        CompanyName: LookUp(
            'Microsoft Entra IDs',
            'A unique identifer for Microsoft Entra ID' = varCurrentUserProfile.Id
        ).'Company Name',
