        IsControlling: false,
        IsControllerOwnData: Not(
            IsBlankOrError(
                First(
                    Filter(
                        colDistinctCurrentUserTeamsRoles,
                        Name = "VSB - Controller Own Data"
                    )
                )
            )
        ),
        IsProjectDataAllCountries: Not(
            IsBlankOrError(
                First(
                    Filter(
                        colDistinctCurrentUserTeamsRoles,
                        Name = "VSB - Project Data All Countries"
                    )
                )
            )
        ),
        CanEditSelectedProject: false,
        EditableCounties: colUserCountries,
        EditableCountiesAsString: Concat(
            colUserCountries,
            name & " ; "
        )
    }
);
Trace(
